{"implementation":"def solve(case):
    def is_int(value):
        return isinstance(value, int) and not isinstance(value, bool)

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("missing required field")
    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list) or not is_int(budget):
        raise ValueError("invalid case fields")
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    allocations = []
    names = []
    seen = set()
    total_minimum = 0
    total_capacity = 0
    for segment in segments:
        if not isinstance(segment, dict):
            raise ValueError("segment must be an object")
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in segment:
                raise ValueError("missing segment field")
        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]
        if not isinstance(name, str) or not is_int(importance):
            raise ValueError("invalid segment field")
        if not is_int(minimum) or not is_int(capacity):
            raise ValueError("invalid quota field")
        if minimum < 0 or capacity < minimum:
            raise ValueError("invalid segment bounds")
        if name in seen:
            raise ValueError("duplicate segment name")
        seen.add(name)
        names.append(name)
        allocations.append(minimum)
        total_minimum += minimum
        total_capacity += capacity

    if budget < total_minimum or budget > total_capacity:
        raise ValueError("budget outside feasible range")

    remaining = budget - total_minimum
    while remaining:
        best = None
        for index, segment in enumerate(segments):
            if allocations[index] >= segment["capacity"]:
                continue
            numerator = segment["importance"]
            denominator = allocations[index] + 1
            if best is None:
                best = (index, numerator, denominator)
            else:
                best_index, best_numerator, best_denominator = best
                if numerator * best_denominator > best_numerator * denominator:
                    best = (index, numerator, denominator)
        if best is None:
            raise ValueError("unable to satisfy budget")
        allocations[best[0]] += 1
        remaining -= 1

    return {
        "allocations": allocations,
        "by_name": {name: allocation for name, allocation in zip(names, allocations)},
        "total": sum(allocations),
    }"}
